from typing import List

def solve_tsp(distances: List[List[int]]) -> int:
    num_cities = len(distances)

    # Helper function to calculate the minimum cost of TSP starting from city 0 and visiting all other cities exactly once.
    def tsp_helper(current_city: int, visited: set, cost_so_far: int) -> int:
        if len(visited) == num_cities - 1:
            return distances[current_city][0] + cost_so_far

        min_cost = float('inf')

        for next_city in range(num_cities):
            if next_city not in visited and distances[current_city][next_city] != 0:
                visited.add(next_city)
                min_cost = min(min_cost, tsp_helper(next_city, visited, cost_so_far + distances[current_city][next_city]))
                visited.remove(next_city)

        return min_cost

    # Start the recursion from city 0 with an initial cost of 0.
    return tsp_helper(0, {0}, 0)

