def solve_octagon_prob(numbers: List[int]) -> int:
    def is_arithmetic_progression(a, b, c):
        # Check if a, b, c are in arithmetic progression
        return (b - a) == (c - b)

    def count_arithmetic_progressions(nums):
        n = len(nums)
        count = 0
        for i in range(n):
            for j in range(i + 1, n):
                for k in range(j + 1, n):
                    if is_arithmetic_progression(nums[i], nums[j], nums[k]):
                        count += 1
        return count

    # Total ways to choose 3 vertices out of 8
    total_ways = 8 * 7 * 6 // (3 * 2)

    # Count valid right triangles and arithmetic progressions
    valid_triangles = [
        (0, 4), (1, 5), (2, 6), (3, 7)  # These are the pairs of opposite vertices in a regular octagon
    ]
    count_valid_arithmetic_progressions = 0

    for i, j in valid_triangles:
        nums = sorted([numbers[i], numbers[j]])
        if is_arithmetic_progression(nums[0], nums[1], max(numbers)):
            count_valid_arithmetic_progressions += 1

    # Calculate the probability
    favorable_outcomes = count_valid_arithmetic_progressions * 2  # Each valid triangle can be chosen in 3 ways (ABC, ACB, BAC)
    total_outcomes = total_ways - len(valid_triangles) * 3  # Subtract invalid choices

    from fractions import Fraction
    probability = Fraction(favorable_outcomes, total_outcomes).limit_denominator()

    return probability.numerator + probability.denominator

